function decodeBase64113c(b64: string): Uint8Array {
  const alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
  const lut = new Int16Array(128)
  lut.fill(-1)
  for (let i = 0; i < 64; i++) lut[alpha.charCodeAt(i)] = i
  let pad = 0
  if (b64.endsWith('==')) pad = 2
  else if (b64.endsWith('=')) pad = 1
  const outLen = ((b64.length * 3) >>> 2) - pad
  const out = new Uint8Array(outLen)
  let o = 0
  for (let i = 0; i < b64.length; i += 4) {
    const c0 = lut[b64.charCodeAt(i)]!
    const c1 = lut[b64.charCodeAt(i + 1)]!
    const c2 = b64.charCodeAt(i + 2) === 61 ? 0 : lut[b64.charCodeAt(i + 2)]!
    const c3 = b64.charCodeAt(i + 3) === 61 ? 0 : lut[b64.charCodeAt(i + 3)]!
    const v = (c0 << 18) | (c1 << 12) | (c2 << 6) | c3
    if (o < outLen) out[o++] = (v >>> 16) & 0xff
    if (o < outLen) out[o++] = (v >>> 8) & 0xff
    if (o < outLen) out[o++] = v & 0xff
  }
  return out
}

