    const aidist: DiffVec113c = [dv.getInt16(o + 22, true), dv.getInt16(o + 24, true), dv.getInt16(o + 26, true)]
    const aip1: DiffVec113c = [dv.getInt16(o + 28, true), dv.getInt16(o + 30, true), dv.getInt16(o + 32, true)]
    const aip2: DiffVec113c = [dv.getInt16(o + 34, true), dv.getInt16(o + 36, true), dv.getInt16(o + 38, true)]
