const LEVEL_DIFF_EXP_ABOVE = [256, 256, 256, 256, 256, 256, 207, 159, 110, 61, 13] as const
const LEVEL_DIFF_EXP_UNDER25 = [256, 256, 256, 256, 256, 256, 225, 174, 92, 38, 5] as const

export function calculateKillExperienceGainPure113c(params: {
  readonly rawExp: number
  readonly clvl: number
  readonly mlvl: number
  readonly addExpPct: number
}): number {
  const characterLevel = Math.max(1, Math.floor(params.clvl))
  if (characterLevel >= 99) return 0
  let exp = Math.trunc(params.rawExp)
  if (exp > 0x7fffff) exp = 0x7fffff
  else if (exp <= 0) return 1

  const monsterLevel = params.mlvl > 0 ? Math.floor(params.mlvl) : characterLevel
  if (monsterLevel <= characterLevel) {
    const diff = Math.min(10, characterLevel - monsterLevel)
    const mod = LEVEL_DIFF_EXP_ABOVE[diff]!
    if (mod !== 256) exp = mulDiv113c(mod, exp, 256)
  } else if (characterLevel < 25) {
    const diff = Math.min(10, monsterLevel - characterLevel)
    const mod = LEVEL_DIFF_EXP_UNDER25[diff]!
    if (mod !== 256) exp = mulDiv113c(mod, exp, 256)
  } else {
    exp = mulDiv113c(characterLevel, exp, monsterLevel)
  }

  if (exp > 0) {
    const clampedLv = Math.max(1, Math.min(99, characterLevel))
    const expRatio = EXP_RATIOS_113C[clampedLv]!
    const shift = 10
    const limit = 0x7fffffff >> ((shift + (expRatio >> shift)) & 31)
    exp = exp > limit ? Math.imul(exp >> shift, expRatio) : Math.imul(expRatio, exp) >> shift
  } else {
    exp = 0
  }

  const stat85 = Math.trunc(params.addExpPct)
  if (stat85 !== 0) {
    exp += mulDiv113c(stat85, exp, 100)
  }
  return exp > 0 ? exp : 0
}

